	if root == "" {
		cwd, err := os.Getwd()
		if err == nil {
			root = cwd
		}
	}
	return filepath.Join(root, ".pipeline-workspace", "streamma-routing")
}

func (runner *Runner) writeStreamMAJSONArtifactInDir(dir, fileName string, value interface{}) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
